import heapq
from collections import deque

ARETES = [
    ("A", "B", 7), ("A", "C", 9), ("A", "F", 14),
    ("B", "C", 10), ("B", "D", 15), ("C", "D", 11),
    ("C", "F", 2), ("D", "E", 6), ("E", "F", 9),
]


def construire(sommets, aretes, non_oriente=True):
    index = {s: i for i, s in enumerate(sommets)}
    n = len(sommets)
    matrice = [[0] * n for _ in range(n)]
    liste = {s: [] for s in sommets}
    for u, v, poids in aretes:
        matrice[index[u]][index[v]] = poids
        liste[u].append((v, poids))
        if non_oriente:
            matrice[index[v]][index[u]] = poids
            liste[v].append((u, poids))
    return matrice, liste, index


def bfs(graphe, depart):
    decouverts = {depart}
    file = deque([depart])
    distances = {depart: 0}
    ordre = []
    while file:
        sommet = file.popleft()
        ordre.append(sommet)
        for voisin, _ in graphe[sommet]:
            if voisin not in decouverts:
                decouverts.add(voisin)
                distances[voisin] = distances[sommet] + 1
                file.append(voisin)
    return ordre, distances


def dfs_recursif(graphe, depart, decouverts=None, ordre=None):
    if decouverts is None:
        decouverts, ordre = set(), []
    decouverts.add(depart)
    ordre.append(depart)
    for voisin, _ in graphe[depart]:
        if voisin not in decouverts:
            dfs_recursif(graphe, voisin, decouverts, ordre)
    return ordre


def dfs_pile(graphe, depart):
    decouverts = {depart}
    pile = [depart]
    ordre = []
    while pile:
        sommet = pile.pop()
        ordre.append(sommet)
        for voisin, _ in graphe[sommet]:
            if voisin not in decouverts:
                decouverts.add(voisin)
                pile.append(voisin)
    return ordre


def dijkstra(graphe, depart):
    distances = {s: float("inf") for s in graphe}
    predecesseurs = {}
    distances[depart] = 0
    file = [(0, depart)]
    while file:
        d, u = heapq.heappop(file)
        if d > distances[u]:
            continue
        for v, poids in graphe[u]:
            candidate = d + poids
            if candidate < distances[v]:
                distances[v] = candidate
                predecesseurs[v] = u
                heapq.heappush(file, (candidate, v))
    return distances, predecesseurs


def chemin(predecesseurs, depart, arrivee):
    suite = [arrivee]
    while suite[-1] != depart:
        suite.append(predecesseurs[suite[-1]])
    return list(reversed(suite))


sommets = ["A", "B", "C", "D", "E", "F"]
_, graphe, _ = construire(sommets, ARETES)
print(bfs(graphe, "A"))
print(dfs_recursif(graphe, "A"))
print(dfs_pile(graphe, "A"))
dist, prec = dijkstra(graphe, "A")
print(dist)
print(chemin(prec, "A", "E"))  # A, C, F, E pour un coût de 20
